\FOR{$t=1,2,\ldots,T$}
\STATE For each link $(n,m)\in {\mathcal L}$, pass the maximum loss magnitude for this round $M\lVert \bm Q_m(t)-\bm Q_n(t)\rVert_\infty$ to $\texttt{AdaPFOL}\xspace_{n,m}$. Pick link allocation $\bm a_{n,m}(t)\in \triangle({\mathcal N})$ as the output of $\texttt{AdaPFOL}\xspace_{n,m}$.
\STATE Observe arrival rates $\bm \lambda(t)\in \Lambda$. \COMMENT{In the utility maximization algorithm \texttt{UMO}\textsuperscript{\texttt{2}}\xspace (\Cref{alg:utility}), this step will be replaced by another algorithmic component.}
\STATE Observe capacities $\{C_{n,m}(t)\}_{(n,m)\in {\mathcal L}}$ and actual data transmissions $\{\mu_{n,m}^{(k)}(t)\}_{(n,m)\in {\mathcal L},k\in {\mathcal N}}$.
\STATE Calculate queue lengths $\bm Q(t+1)$ from $\bm Q(t)$ according to \Cref{eq:multi-hop stability dynamics}.
\STATE For each link $(n,m)\in {\mathcal L}$, pass the loss vector $C_{n,m}(t)(\bm Q_m(t)-\bm Q_n(t))$ to $\texttt{AdaPFOL}\xspace_{n,m}$.

\FOR{$t=1,2,\ldots$}
\STATE Observe the maximum loss magnitude $G_t>0$ for this round.
\IF{$G_t>G$}
\STATE Set $G=2G_t$. Reset $\mathcal A$ as a new instance of the algorithm in \Cref{lem:OLO guarantee} with action set $\mathcal X$.
\ENDIF
\STATE Output the ouptut of $\mathcal A$. Observe loss vector $\bm g_t$ (such that $\lVert \bm g_t\rVert_\infty\le G_t$). Feed $G^{-1}\bm g_t$ to $\mathcal A$.

\FOR{$t=1,2,\ldots,T$}
\STATE For each link $(n,m)\in {\mathcal L}$, pass the maximum loss magnitude for this round $M\lVert \bm Q_m(t)-\bm Q_n(t)\rVert_\infty$ to $\texttt{AdaPFOL}\xspace_{n,m}$. Pick link allocation $\bm a_{n,m}(t)\in \triangle({\mathcal N})$ as the output of $\texttt{AdaPFOL}\xspace_{n,m}$.
\STATE {\color{blue}Call $\texttt{AdaBGD}\xspace$ with learning rates defined in \Cref{eq:true learning rate in BCO}. Pick arrival rates $\bm \lambda(t)\in \Lambda$ as its output.
\begin{align}
\eta_t&=\left (C^\lambda T^{1/2 - \delta_\lambda}\middle / \substack{\left (C^\lambda T^{1/2 - \delta_\lambda}\right )^{7/3} \left (4r^{-3} d^2 \right )^{28/9} \left (M+R\right )^{4/3}+\\
C^\lambda T^{1/2-\delta_\lambda} (r^{-3} d^2 VG^2 / L)^{4/3}+\\
\sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}}\right )^{3/4}, \nonumber\\
\delta_t &= \left (\eta_t d^2 \frac{(\lVert \bm Q(t)\rVert_\infty + VG)^2}{(\lVert \bm Q(t)\rVert_2 + VL)}\right )^{1/3},\quad \alpha_t = \frac{\delta_t}{r}. \end{align}}
\STATE Observe capacities $\{C_{n,m}(t)\}_{(n,m)\in {\mathcal L}}$ and actual data transmissions $\{\mu_{n,m}^{(k)}(t)\}_{(n,m)\in {\mathcal L},k\in {\mathcal N}}$.
\STATE Calculate queue lengths $\bm Q(t+1)$ from $\bm Q(t)$ according to \Cref{eq:multi-hop stability dynamics}.
\STATE For each link $(n,m)\in {\mathcal L}$, pass the loss vector $C_{n,m}(t)(\bm Q_m(t)-\bm Q_n(t))$ to $\texttt{AdaPFOL}\xspace_{n,m}$.
\STATE {\color{blue} Observe the collected utility $g_t(\bm \lambda(t))$. Pass the loss $\langle \bm Q(t),\bm \lambda (t)\rangle - V g_t(\bm \lambda(t))$ to $\texttt{AdaBGD}\xspace$.}

{\color{blue}Call $\texttt{AdaBGD}\xspace$ with learning rates defined in \Cref{eq:true learning rate in BCO}. Pick arrival rates $\bm \lambda(t)\in \Lambda$ as its output.
\begin{align}
\eta_t&=\left (C^\lambda T^{1/2 - \delta_\lambda}\middle / \substack{\left (C^\lambda T^{1/2 - \delta_\lambda}\right )^{7/3} \left (4r^{-3} d^2 \right )^{28/9} \left (M+R\right )^{4/3}+\\
C^\lambda T^{1/2-\delta_\lambda} (r^{-3} d^2 VG^2 / L)^{4/3}+\\
\sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}}\right )^{3/4}, \nonumber\\
\delta_t &= \left (\eta_t d^2 \frac{(\lVert \bm Q(t)\rVert_\infty + VG)^2}{(\lVert \bm Q(t)\rVert_2 + VL)}\right )^{1/3},\quad \alpha_t = \frac{\delta_t}{r}. \end{align}}

\FOR{$t=1,2,\ldots,T$}
\STATE Calculate this round's action $\bm x_t\in \mathcal X$, observe loss $\ell_t(x_t)$, and update internal variable $\bm y_{t+1}$:
\begin{equation} \bm x_t=\bm y_t+\delta \bm s_t,\quad \bm y_{t+1}=\text{Proj}_{(1-\alpha_t)\mathcal X}\left [\bm y_t-\eta_t \frac{d}{\delta_t} \ell_t(\bm x_t) \bm s_t\right ],
\end{equation}
where $\bm s_t\in \mathbb R^d$ is a uniformly sampled unit vector used to estimate gradients \citep{flaxman2005online}.
